    if raw is None:
        return None

    if not isinstance(raw, list):
        import json

        try:
            raw = json.loads(str(raw))
        except (json.JSONDecodeError, TypeError, ValueError):
            return set()
        if not isinstance(raw, list):
            return set()

    modules: set[str] = set()
