class Solution:
    def check_coords(self, ds, schema: 'DatasetSchema') -> list['CoreCheckResult']:
        core_check_results = []
        for field in schema.fields:
            if field not in ds.data:
                core_check_results.append(CoreCheckResult(field, False))
            else:
                value = ds.data[field]
                if not self._validate_value(value, schema.fields[field]):
                    core_check_results.append(CoreCheckResult(field, False))
                else:
                    core_check_results.append(CoreCheckResult(field, True))
        return core_check_results

    def _validate_value(self, value, field_type: str) -> bool:
        try:
            if field_type == "int":
                int(value)
            elif field_type == "float":
                float(value)
            else:
                raise ValueError(f"Unsupported type: {field_type}")
            return True
    except (ValueError, TypeError):
        return False
