            coords[0],
            coords[1],
            coords[2] - coords[0],
            coords[3] - coords[1],
        ]
    if target == "voc":
        return list(coords)
    if target == "yolo":
        return [
            (coords[0] + coords[2]) / 2 / img_size[0],
            (coords[1] + coords[3]) / 2 / img_size[1],
            (coords[2] - coords[0]) / img_size[0],
            (coords[3] - coords[1]) / img_size[1],
        ]
    raise ValueError(f"Unsupported target format: {target}")

