class Solution:
    def read_json_metadata(self, path):
        """Read last_version and records from a dataset JSON file."""
        try:
            with open(path) as f:
                data = json.load(f)
            versions = data.get("versions", [])
            if not versions:
                return {}
            latest = versions[-1]
            return {
                "last_version": latest.get("version", ""),
                "records": str(latest.get("records", "")),
            }
