def infer_filename(self) -> str | None:
    """
    If an explicit archive_name is not given, we still want the file inside the zip
    file not to be named something.tar, because that causes confusion (GH39465).
    """
    if self.name is None:
        return None

    filename = Path(self.name)
    if filename.suffix == ".tar":
        return filename.with_suffix("").name
    elif filename.suffix in (".tar.gz", ".tar.bz2", ".tar.xz"):
        return filename.with_suffix("").with_suffix("").name
    return filename.name

async def _search_all(self, query: str) -> dict[str, list[dict[str, Any]]]:
    """Execute a single unfiltered search and categorize results."""
    results: dict[str, list[dict[str, Any]]] = {
        "songs": [],
        "albums": [],
        "artists": [],
        "playlists": [],
    }

    ytmusic = cast("YTMHostBase", self.app).ytmusic
