import ipaddress
import re

class Solution:
    def _blocked_ip(self, ip):
        """True for addresses an authoritative NS must not point at (SSRF guard)."""
        try:
            a = ipaddress.ip_address(ip)
        except ValueError:
            return True
        return (
            a.is_private
            or a.is_loopback
            or a.is_link_local
            or a.is_multicast
            or a.is_reserved
            or a.is_unspecified
        )

