def _which(prog, _cache={}):
    """Return path to ``prog`` if it's executable on PATH, else None.

    v4.6.0: memoized in a default-arg dict — tool paths are immutable for the
    agent's lifetime and this is called dozens of times per heartbeat
    (stat-walking PATH each call). (A plain dict rather than @lru_cache so the
    function source stays decorator-free for source-extraction tests.)

    v3.13.0: also searches the standard sbin dirs even when they're absent from
    a minimal service PATH — firewall tools (iptables/nft) live in /usr/sbin and
    /sbin, and a systemd unit's PATH often omits them, which made firewall
    detection report "unknown"."""
    if prog in _cache:
        return _cache[prog]
    seen = []
    for d in os.environ.get('PATH', '').split(':'):
        if d:
            seen.append(d)
    for d in ('/usr/sbin', '/sbin', '/usr/bin', '/bin', '/usr/local/sbin', '/usr/local/bin'):
        if d not in seen:
            seen.append(d)
    result = None
    for d in seen:
        full = os.path.join(d, prog)
        if os.path.isfile(full) and os.access(full, os.X_OK):
            result = full
            break
    _cache[prog] = result
    return result

def parse_tsv_file(filepath, batch_size=50000, filter_year=None):
    """Parse a gzipped TSV file and yield batches of records."""
    import csv

    with gzip.open(filepath, "rt", encoding="utf-8") as gz_file:
        reader = csv.DictReader(gz_file, delimiter="\t")
        batch = []
        total_processed = 0

        for row in reader:
            # map missing values to None
            row = {k: (None if v == "\\N" else v) for k, v in row.items()}

            # remove nsfw data
            if row.get("isAdult") == "1":
                continue

            if filter_year:
                start_year = int(row.get("startYear", 0) or 0)
                if start_year < filter_year:
                    continue

            batch.append(row)
            total_processed += 1

            if len(batch) >= batch_size:
                yield batch
                batch = []

        # Yield any remaining records
        if batch:
            yield batch

        print(f"Finished processing {total_processed:,} titles.")

