async def get_best_solution(self) -> Dict[str, Any]:
    """Return the best reasoning path found."""
    async with self.lock:
        if self.best_solution is None:
            # Fallback: most visited path from root
            path = []
            current = self.root
            while current.children:
                current = max(current.children, key=lambda c: c.visits)
                path.append(current.state)
            return {"path": path, "reward": 0.0}

        return {
            "path": self.best_solution,
            "reward": self.best_reward,
            "total_simulations": self.root.visits,
        }

def _short_src(src: Optional[str]) -> Optional[str]:
    """Compact a per-field source tag for non-JSON display.

    ``env:FLOW_CODEX_EFFORT`` → ``env`` (keeps line short; JSON output
    still has the full key for anyone who cares).
    """
    if src is None:
        return None
    if src.startswith("env:"):
        return "env"
    if src == "registry_default":
        return "registry"
    return src

