async def _load_history(
    owner_user_id: UUID, session_id: str, user_id: UUID, limit: int | None = None
) -> list[dict]:
    """Rebuild the [{role, content}] conversation from stored session events.

    `limit` caps the replay to the most recent N turns — for the Slack agent's
    single ever-growing per-user session, older context is recalled via the
    `search_history` tool rather than replayed verbatim."""
    events = await memory_service.read_session_events(owner_user_id, session_id, user_id)
    history: list[dict] = []
    for e in events:
        content = (e.get("content") or "").strip()
        if not content:
            continue
        if e["event_type"] == "user_message":
            history.append({"role": "user", "content": content})
        elif e["event_type"] == "assistant_message":
            history.append({"role": "assistant", "content": content})
    if limit is not None:
        return history[-limit:]
    return history

def homo_tuple_typed_attrs(
    draw,
    defaults: FeatureFlag = "sometimes",
    legacy_types_only=False,
    kw_only: FeatureFlag = "sometimes",
):
    """
    Generate a tuple of an attribute and a strategy that yields homogenous
    tuples for that attribute. The tuples contain strings.
    """
    default = NOTHING
    val_strat = tuples(text(), text(), text())
    if defaults == "always" or (defaults == "sometimes" and draw(booleans())):
        default = draw(val_strat)
    return (
        field(
            type=draw(
                sampled_from(
                    [tuple[str, ...], tuple, Tuple, Tuple[str, ...]]
                    if not legacy_types_only
                    else [tuple, Tuple, Tuple[str, ...]]
                )
            ),
            default=default,
            kw_only=(
                draw(booleans()) if kw_only == "sometimes" else (kw_only == "always")
            ),
        ),
        val_strat,
    )

